import 'package:flutter/material.dart';
import 'package:lazerus_core/lazerus_core.dart';

import '../../../../../core/macros/modifiers/color/color_modifier.dart';
import '../macro_editor_node_module.dart';

final class ColorMacroEditorNodeModule extends MacroEditorNodeModule {
  @override
  String get kind => colorModifierKind;

  @override
  Iterable<MacroEditorPaletteEntry> paletteEntries(
    MacroEditorNodePresentationState state,
  ) => <MacroEditorPaletteEntry>[
    const MacroEditorPaletteEntry(
      id: 'palette.color',
      moduleKind: colorModifierKind,
      section: MacroEditorPaletteSection.modules,
      icon: Icons.palette_outlined,
      title: 'Color',
      subtitle: 'HSV source',
    ),
  ];

  @override
  MacroNode? createNode(
    MacroEditorPaletteEntry entry, {
    required MacroEditorNewId newId,
  }) => _nodeWithConfiguration(
    MacroNode(
      id: newId(),
      kind: kind,
      displayName: 'Color',
      ports: const <MacroPortDeclaration>[],
    ),
    ColorModifierConfiguration(),
  );

  @override
  double cardBodyHeight(MacroNode node) => 54;

  @override
  Widget buildCardBody(
    BuildContext context,
    MacroEditorNodeViewContext nodeContext,
  ) {
    try {
      final configuration = ColorModifierConfiguration.fromNodeParameters(
        nodeContext.node.parameters,
      );
      return _CompactHuePicker(
        hue: configuration.hue,
        enabled: nodeContext.state.enabled,
        onChanged: (hue) {
          nodeContext.replaceNode(
            _nodeWithConfiguration(
              nodeContext.node,
              ColorModifierConfiguration(
                hue: hue,
                saturation: configuration.saturation,
                value: configuration.value,
              ),
            ),
          );
        },
      );
    } on FormatException {
      return const Text('Color configuration needs repair.');
    }
  }

  @override
  Widget buildInspector(
    BuildContext context,
    MacroEditorNodeViewContext nodeContext,
  ) => MacroEditorNodeInspectorCard(
    icon: Icons.palette_outlined,
    title: titleFor(nodeContext.node),
    enabled: nodeContext.state.enabled,
    onRemove: nodeContext.removeNode,
    child: const Text('Use the hue control directly on this plot card.'),
  );

  MacroNode _nodeWithConfiguration(
    MacroNode node,
    ColorModifierConfiguration configuration,
  ) => node.copyWith(
    parameters: configuration.toNodeParameters(),
    ports: ColorModifierFactory.portsForNode(node.id),
  );
}

/// Direct-manipulation hue control owned by the Color presentation module.
final class _CompactHuePicker extends StatelessWidget {
  const _CompactHuePicker({
    required this.hue,
    required this.enabled,
    required this.onChanged,
  });

  final double hue;
  final bool enabled;
  final ValueChanged<double> onChanged;

  @override
  Widget build(BuildContext context) => LayoutBuilder(
    builder: (context, constraints) {
      void update(Offset localPosition) {
        if (!enabled || constraints.maxWidth <= 0) return;
        onChanged(
          (localPosition.dx.clamp(0, constraints.maxWidth) /
                  constraints.maxWidth *
                  360)
              .toDouble(),
        );
      }

      final thumbAlignment = (hue / 180 - 1).clamp(-1.0, 1.0).toDouble();
      return Semantics(
        label: 'Color hue ${hue.round()} degrees',
        slider: true,
        child: GestureDetector(
          onTapDown: enabled
              ? (details) => update(details.localPosition)
              : null,
          onHorizontalDragUpdate: enabled
              ? (details) => update(details.localPosition)
              : null,
          child: DecoratedBox(
            decoration: BoxDecoration(
              borderRadius: BorderRadius.circular(9),
              gradient: const LinearGradient(
                colors: <Color>[
                  Colors.red,
                  Colors.yellow,
                  Colors.green,
                  Colors.cyan,
                  Colors.blue,
                  Colors.purple,
                  Colors.red,
                ],
              ),
            ),
            child: Stack(
              alignment: Alignment(thumbAlignment, 0),
              children: <Widget>[
                const SizedBox.expand(),
                Container(
                  width: 18,
                  height: 18,
                  decoration: BoxDecoration(
                    shape: BoxShape.circle,
                    color: HSVColor.fromAHSV(1, hue, 1, 1).toColor(),
                    border: Border.all(color: Colors.white, width: 2),
                    boxShadow: const <BoxShadow>[
                      BoxShadow(blurRadius: 2, color: Color(0x99000000)),
                    ],
                  ),
                ),
                Align(
                  alignment: const Alignment(0, 1),
                  child: Padding(
                    padding: const EdgeInsets.only(bottom: 1),
                    child: Text(
                      'H ${hue.round()}°',
                      style: const TextStyle(
                        color: Colors.white,
                        fontSize: 10,
                        fontWeight: FontWeight.w700,
                        shadows: <Shadow>[
                          Shadow(color: Colors.black, blurRadius: 2),
                        ],
                      ),
                    ),
                  ),
                ),
              ],
            ),
          ),
        ),
      );
    },
  );
}
